import{_ as t,a0 as l,w as o,s as d,ao as c,I as i,x as a,a1 as e,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"監控 Linux 服務器活動的幾個命令 | LCTT x X-CMD","titleTemplate":false,"description":"監控 Linux 服務器活動的幾個命令 | LCTT (201902) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"監控 Linux 服務器活動的幾個命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"監控 Linux 服務器活動的幾個命令 | LCTT (201902) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201902/20190123 Commands to help you monitor activity on your Linux server","title":"監控 Linux 服務器活動的幾個命令","tag":"201902","desc":""},"relativePath":"201902/20190123 Commands to help you monitor activity on your Linux server.md","filePath":"[post].md"}'),r={name:"201902/20190123 Commands to help you monitor activity on your Linux server.md"};function h(u,s,g,k,b,m){const n=l("Link");return o(),d("div",null,[s[15]||(s[15]=c(`<h1 id="監控-linux-服務器活動的幾個命令" tabindex="-1">監控 Linux 服務器活動的幾個命令 <a class="header-anchor" href="#監控-linux-服務器活動的幾個命令" aria-label="Permalink to “監控 Linux 服務器活動的幾個命令”">​</a></h1><blockquote><p><code>watch</code>、<code>top</code> 和 <code>ac</code> 命令為我們監視 Linux 服務器上的活動提供了一些十分高效的途徑。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2019/01/owl-face-100785829-large.jpg" alt=""></p><p>為了在獲取系統活動時更加輕鬆，Linux 系統提供了一系列相關的命令。在這篇文章中，我們就一起來看看這些對我們很有幫助的命令吧。</p><h3 id="watch-命令" tabindex="-1">watch 命令 <a class="header-anchor" href="#watch-命令" aria-label="Permalink to “watch 命令”">​</a></h3><p><code>watch</code> 是一個用來輕鬆地重複檢測 Linux 系統中一系列數據命令，例如用户活動、正在運行進程、登錄、內存使用等。這個命令實際上是重複地運行一個特定的命令，每次都會重寫之前顯示的輸出，它提供了一個比較方便的方式用以監測在你的系統中發生的活動。</p><p>首先以一個基礎且不是特別有用的命令開始，你可以運行 <code>watch -n 5 date</code>，然後你可以看到在終端中顯示了當前的日期和時間，這些數據會每五秒更新一次。你可能已經猜到了，<code>-n 5</code> 選項指定了運行接下來一次命令需要等待的秒數。默認是 2 秒。這個命令將會一直運行並按照指定的時間更新顯示，直到你使用 <code>^C</code> 停下它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Every 5.0s: date                             butterfly: Wed Jan 23 15:59:14 2019</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Wed Jan 23 15:59:14 EST 2019</span></span></code></pre></div><p>下面是一個更有趣的命令實例，你可以監控一個在服務器中登錄用户的列表，該列表會按照指定的時間定時更新。就像下面寫到的，這個命令會每 10 秒更新一次這個列表。登出的用户將會從當前顯示的列表中消失，那些新登錄的將會被添加到這個表格當中。如果沒有用户再登錄或者登出，這個表格跟之前顯示的將不會有任何不同。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ watch -n 10 who</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Every 10.0s: who                             butterfly: Tue Jan 23 16:02:03 2019</span></span>
<span class="line"><span></span></span>
<span class="line"><span>shs      :0           2019-01-23 09:45 (:0)</span></span>
<span class="line"><span>dory     pts/0        2019-01-23 15:50 (192.168.0.5)</span></span>
<span class="line"><span>nemo     pts/1        2019-01-23 16:01 (192.168.0.15)</span></span>
<span class="line"><span>shark    pts/3        2019-01-23 11:11 (192.168.0.27)</span></span></code></pre></div><p>如果你只是想看有多少用户登錄進來，可以通過 <code>watch</code> 調用 <code>uptime</code> 命令獲取用户數和負載的平均水平，以及系統的工作狀況。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ watch uptime</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Every 2.0s: uptime                           butterfly: Tue Jan 23 16:25:48 2019</span></span>
<span class="line"><span></span></span>
<span class="line"><span> 16:25:48 up 22 days,  4:38,  3 users,  load average: 1.15, 0.89, 1.02</span></span></code></pre></div><p>如果你想使用 <code>watch</code> 重複一個包含了管道的命令，就需要將該命令用引號括起來，就比如下面這個每五秒顯示一次有多少進程正在運行的命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ watch -n 5 &#39;ps -ef | wc -l&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Every 5.0s: ps -ef | wc -l butterfly: Tue Jan 23 16:11:54 2019</span></span>
<span class="line"><span></span></span>
<span class="line"><span>245</span></span></code></pre></div><p>要查看內存使用，你也許會想要試一下下面的這個命令組合：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ watch -n 5 free -m</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Every 5.0s: free -m butterfly: Tue Jan 23 16:34:09 2019</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Every 5.0s: free -m                          butterfly: Tue Jan 23 16:34:09 2019</span></span>
<span class="line"><span></span></span>
<span class="line"><span>              total        used        free      shared  buff/cache   available</span></span>
<span class="line"><span>Mem:           5959         776        3276          12        1906        4878</span></span>
<span class="line"><span>Swap:          2047           0        2047</span></span></code></pre></div><p>你可以在 <code>watch</code> 後添加一些選項查看某個特定用户下運行的進程，不過 <code>top</code> 為此提供了更好的選擇。</p><h3 id="top-命令" tabindex="-1">top 命令 <a class="header-anchor" href="#top-命令" aria-label="Permalink to “top 命令”">​</a></h3><p>如果你想查看某個特定用户下的進程，<code>top</code> 命令的 <code>-u</code> 選項可以很輕鬆地幫你達到這個目的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ top -u nemo</span></span>
<span class="line"><span>top - 16:14:33 up 2 days,  4:27,  3 users,  load average: 0.00, 0.01, 0.02</span></span>
<span class="line"><span>Tasks: 199 total,   1 running, 198 sleeping,   0 stopped,   0 zombie</span></span>
<span class="line"><span>%Cpu(s):  0.0 us,  0.2 sy,  0.0 ni, 99.8 id,  0.0 wa,  0.0 hi,  0.0 si,  0.0 st</span></span>
<span class="line"><span>MiB Mem :   5959.4 total,   3277.3 free,    776.4 used,   1905.8 buff/cache</span></span>
<span class="line"><span>MiB Swap:   2048.0 total,   2048.0 free,      0.0 used.   4878.4 avail Mem</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  PID USER      PR  NI    VIRT    RES    SHR S  %CPU  %MEM     TIME+ COMMAND</span></span>
<span class="line"><span>23026 nemo      20   0   46340   7820   6504 S   0.0   0.1   0:00.05 systemd</span></span>
<span class="line"><span>23033 nemo      20   0  149660   3140     72 S   0.0   0.1   0:00.00 (sd-pam)</span></span>
<span class="line"><span>23125 nemo      20   0   63396   5100   4092 S   0.0   0.1   0:00.00 sshd</span></span>
<span class="line"><span>23128 nemo      20   0   16836   5636   4284 S   0.0   0.1   0:00.03 zsh</span></span></code></pre></div><p>你可能不僅可以看到某個用户下的進程，還可以查看每個進程所佔用的資源，以及系統總的工作狀況。</p><h3 id="ac-命令" tabindex="-1">ac 命令 <a class="header-anchor" href="#ac-命令" aria-label="Permalink to “ac 命令”">​</a></h3><p>如果你想查看系統中每個用户登錄的時長，可以使用 <code>ac</code> 命令。運行該命令之前首先需要安裝 <code>acct</code>（Debian 等）或者 <code>psacct</code>（RHEL、Centos 等）包。</p><p><code>ac</code> 命令有一系列的選項，該命令從 <code>wtmp</code> 文件中拉取數據。這個例子展示的是最近用户登錄的總小時數。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ac</span></span>
<span class="line"><span>        total     1261.72</span></span></code></pre></div><p>這個命令顯示了用户登錄的總的小時數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ac -p</span></span>
<span class="line"><span>        shark                                5.24</span></span>
<span class="line"><span>        nemo                                 5.52</span></span>
<span class="line"><span>        shs                               1251.00</span></span>
<span class="line"><span>        total     1261.76</span></span></code></pre></div><p>這個命令顯示了每天登錄的用户小時數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ac -d | tail -10</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Jan 11  total        0.05</span></span>
<span class="line"><span>Jan 12  total        1.36</span></span>
<span class="line"><span>Jan 13  total       16.39</span></span>
<span class="line"><span>Jan 15  total       55.33</span></span>
<span class="line"><span>Jan 16  total       38.02</span></span>
<span class="line"><span>Jan 17  total       28.51</span></span>
<span class="line"><span>Jan 19  total       48.66</span></span>
<span class="line"><span>Jan 20  total        1.37</span></span>
<span class="line"><span>Jan 22  total       23.48</span></span>
<span class="line"><span>Today   total        9.83</span></span></code></pre></div><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>Linux 系統上有很多命令可以用於檢查系統活動。<code>watch</code> 命令允許你以重複的方式運行任何命令，並觀察輸出有何變化。<code>top</code> 命令是一個專注於用户進程的最佳選項，以及允許你以動態方式查看進程的變化，還可以使用 <code>ac</code> 命令檢查用户連接到系統的時間。</p><hr>`,32)),i("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://www.networkworld.com/article/3335200/linux/how-to-monitor-activity-on-your-linux-server.html"},{default:p(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3335200/linux/how-to-monitor-activity-on-your-linux-server.html",-1)])]),_:1})]),i("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:p(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),e(n,{href:"https://github.com/dianbanjiu"},{default:p(()=>[...s[4]||(s[4]=[a("dianbanjiu",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const w=t(r,[["render",h]]);export{x as __pageData,w as default};
